// MineBench: Choo-Choo Train — steam locomotive + tender + 2 boxcars + track + environment
// Train runs along Z axis, front facing +Z. Center ~ x=128, z=128.

// ---- helpers ----
function box(x1,y1,z1,x2,y2,z2,t){
  for(let x=Math.min(x1,x2);x<=Math.max(x1,x2);x++)
  for(let y=Math.min(y1,y2);y<=Math.max(y1,y2);y++)
  for(let z=Math.min(z1,z2);z<=Math.max(z1,z2);z++)
    block(x,y,z,t);
}
function cylXZ(cx,cz,r,h,y0,t){
  for(let y=0;y<h;y++)
  for(let x=-r;x<=r;x++)
  for(let z=-r;z<=r;z++)
    if(x*x+z*z<=r*r) block(cx+x,y0+y,cz+z,t);
}
function wheel(cx,cz,r,y0,t){
  cylXZ(cx,cz,r,1,y0,t);
  for(let a=0;a<8;a++){
    let s=Math.cos(a*Math.PI/4)*r, st=Math.sin(a*Math.PI/4)*r;
    for(let i=1;i<r;i++){
      block(cx+Math.round(s*i/r),y0,cz+Math.round(st*i/r),'iron_block');
      block(cx-Math.round(s*i/r),y0,cz-Math.round(st*i/r),'iron_block');
    }
  }
  block(cx,y0,cz,'iron_block');
}

